package com.myaaptha.domain.finance;
import static org.assertj.core.api.Assertions.*;
import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockMultipartFile;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.apache.pdfbox.pdmodel.*;
import org.apache.pdfbox.pdmodel.font.*;
class StatementParserTest{
 final StatementParser parser=new StatementParser();final ZoneId zone=ZoneId.of("Asia/Kolkata");
 StatementParser.Parsed csv(String text,String order){return parser.parse(new MockMultipartFile("file","bank.csv","text/csv",text.getBytes(StandardCharsets.UTF_8)),order,zone);}
 @Test void separateDebitCreditColumnsNeverUseTheRunningBalance(){var result=csv("Statement\nDate,Description,Debit,Credit,Balance\n01/02/2026,Bigbasket,\"1,249.50\",,95000.00\n02/02/2026,Payroll,,40000,135000\n", "DMY");assertThat(result.rows()).hasSize(2);assertThat(result.rows().getFirst().amount()).isEqualByComparingTo("1249.50");assertThat(result.rows().getFirst().direction()).isEqualTo("EXPENSE");assertThat(result.rows().getLast().direction()).isEqualTo("INCOME");assertThat(result.rows().getFirst().date()).isEqualTo("2026-01-31T18:30:00Z");}
 @Test void ambiguousPositiveAmountIsFlaggedButExplicitCreditAndNegativeAmountsAreRead(){var result=csv("Date,Description,Amount,Type\n2026-02-01,Unknown,100,\n2026-02-02,Salary,1000,CR\n2026-02-03,Groceries,-35,\n", "DMY");assertThat(result.rows().get(0).issues()).isNotEmpty();assertThat(result.rows().get(1).direction()).isEqualTo("INCOME");assertThat(result.rows().get(2).amount()).isEqualByComparingTo("35");}
 @Test void invalidDatesPrecisionAndForeignCurrencyAreVisibleIssues(){var result=csv("Date,Description,Debit,Credit,Currency\n30/02/2026,Invalid day,10,,INR\n01/02/2026,Too precise,1.001,,INR\n01/02/2026,Foreign,10,,USD\n01/02/2026,Two amounts,10,20,INR\n", "DMY");assertThat(result.rows()).allSatisfy(row->assertThat(row.issues()).isNotEmpty());}
 @Test void chosenDateOrderIsStrict(){assertThat(csv("Date,Description,Amount,Type\n03/04/2026,Test,10,DR\n","DMY").rows().getFirst().date()).isEqualTo("2026-04-02T18:30:00Z");assertThat(csv("Date,Description,Amount,Type\n03/04/2026,Test,10,DR\n","MDY").rows().getFirst().date()).isEqualTo("2026-03-03T18:30:00Z");}
 @Test void spreadsheetDatesAreReadWithoutExecutingFormulas()throws Exception{byte[] bytes;try(var book=new XSSFWorkbook();var out=new ByteArrayOutputStream()){var sheet=book.createSheet();var header=sheet.createRow(0);for(int c=0;c<4;c++)header.createCell(c).setCellValue(List.of("Date","Description","Amount","Type").get(c));var row=sheet.createRow(1);var date=row.createCell(0);date.setCellValue(LocalDateTime.of(2026,2,1,0,0));var style=book.createCellStyle();style.setDataFormat(book.createDataFormat().getFormat("dd/mm/yyyy"));date.setCellStyle(style);row.createCell(1).setCellValue("Grocery");row.createCell(2).setCellValue(100);row.createCell(3).setCellValue("DR");var formula=sheet.createRow(2);formula.createCell(0).setCellValue("2026-02-02");formula.createCell(1).setCellValue("Formula");formula.createCell(2).setCellFormula("100+100");formula.createCell(3).setCellValue("DR");book.write(out);bytes=out.toByteArray();}var parsed=parser.parse(new MockMultipartFile("file","bank.xlsx","application/octet-stream",bytes),"DMY",zone);assertThat(parsed.rows().getFirst().issues()).isEmpty();assertThat(parsed.rows().getLast().issues()).isNotEmpty();}
 @Test void pdfRequiresExplicitAmountDirectionAndIgnoresRunningBalance()throws Exception{byte[] bytes;try(var doc=new PDDocument();var out=new ByteArrayOutputStream()){var page=new PDPage();doc.addPage(page);try(var text=new PDPageContentStream(doc,page)){text.beginText();text.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA),11);text.newLineAtOffset(40,700);text.showText("01/02/2026 Grocery store 100.00 DR 9000.00");text.endText();}doc.save(out);bytes=out.toByteArray();}var result=parser.parse(new MockMultipartFile("file","bank.pdf","application/pdf",bytes),"DMY",zone);assertThat(result.rows().getFirst().amount()).isEqualByComparingTo("100");assertThat(result.rows().getFirst().direction()).isEqualTo("EXPENSE");}
 @Test void semicolonHeadersWinOverCommasInQuotedAmounts(){var parsed=csv("Date;Description;Debit;Credit\n01/02/2026;Groceries;\"12,34,56,789.00\";\n","DMY");assertThat(parsed.rows().getFirst().amount()).isEqualByComparingTo("123456789");}
 @Test void abbreviatedBankColumnNamesAreRecognized(){var result=csv("Date,Narration,Withdrawal Amt.,Deposit Amt.,Closing Balance\n01/02/26,Groceries,100,,900\n","DMY");assertThat(result.rows().getFirst().amount()).isEqualByComparingTo("100");assertThat(result.rows().getFirst().issues()).isEmpty();}
 @Test void noAmountsAreInventedFromBalanceOnlyFiles(){assertThatThrownBy(()->csv("Date,Description,Balance\n01/02/2026,Opening balance,9000\n","DMY")).hasMessageContaining("No transaction columns");}
 @Test void categorySuggestionsDistinguishClothingIncomeAndOwnTransfers(){assertThat(FinanceStatements.suggest("Myntra clothing","EXPENSE")).isEqualTo("CLOTHING");assertThat(FinanceStatements.suggest("Payroll salary","INCOME")).isEqualTo("SALARY");assertThat(FinanceStatements.suggest("Self transfer to own account","INCOME")).isEqualTo("TRANSFER");assertThat(FinanceStatements.suggest("Unknown UPI merchant","EXPENSE")).isEqualTo("OTHER");}
}
